terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
  required_version = ">= 1.0.0"

  # Remote state in Azure Storage so the nightly drift-detection workflow can run
  # `terraform plan` against the real, shared state. Configured at init time via
  # `-backend-config` (see .github/workflows/drift-detection.yaml). For local-only
  # experimentation, run `terraform init -backend=false`.
  backend "azurerm" {}
}

provider "azurerm" {
  features {}
}

variable "resource_group_name" {
  type        = string
  description = "The name of the resource group for Sentinel infrastructure."
  default     = "rg-sentinel-secops-prod"
}

variable "location" {
  type        = string
  description = "The Azure region to deploy resources."
  default     = "eastus"
}

variable "workspace_name" {
  type        = string
  description = "The name of the Log Analytics workspace."
  default     = "law-sentinel-secops-prod"
}

variable "retention_in_days" {
  type        = number
  description = "The workspace data retention in days (Minimum 30 for Sentinel, 90 recommended for prod)."
  default     = 90
}

resource "azurerm_resource_group" "secops" {
  name     = var.resource_group_name
  location = var.location

  tags = {
    Environment = "Production"
    Workload    = "SecurityOperations"
    ManagedBy   = "Terraform"
  }
}

resource "azurerm_log_analytics_workspace" "sentinel" {
  name                = var.workspace_name
  location            = azurerm_resource_group.secops.location
  resource_group_name = azurerm_resource_group.secops.name
  sku                 = "PerGB2018"
  retention_in_days   = var.retention_in_days

  tags = {
    Environment = "Production"
    Workload    = "SecurityOperations"
    ManagedBy   = "Terraform"
  }
}

resource "azurerm_log_analytics_solution" "sentinel" {
  solution_name         = "SecurityInsights"
  location              = azurerm_resource_group.secops.location
  resource_group_name   = azurerm_resource_group.secops.name
  workspace_resource_id = azurerm_log_analytics_workspace.sentinel.id
  workspace_name        = azurerm_log_analytics_workspace.sentinel.name

  plan {
    publisher = "Microsoft"
    product   = "OMSGallery/SecurityInsights"
  }
}

output "resource_group_name" {
  description = "The name of the created Resource Group."
  value       = azurerm_resource_group.secops.name
}

output "log_analytics_workspace_id" {
  description = "The Workspace ID (Used for agent connections and API calls)."
  value       = azurerm_log_analytics_workspace.sentinel.workspace_id
}

output "log_analytics_workspace_name" {
  description = "The actual Azure resource name of the workspace."
  value       = azurerm_log_analytics_workspace.sentinel.name
}

# AWS side of the multi-cloud security architecture.
# Provisions an encrypted, private, versioned CloudTrail log bucket and the OIDC IAM role
# Microsoft Sentinel assumes to ingest AWS logs. Hardened to pass shift-left IaC scanning
# (KMS encryption, public-access block, log-file validation, scoped trust).
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for the CloudTrail integration."
  default     = "us-east-1"
}

variable "sentinel_aws_account_id" {
  type        = string
  description = "AWS account ID Microsoft uses for the Sentinel AWS connector. Do NOT hard-code your own root account."
  default     = "197857026523" # Microsoft-published Sentinel S3 connector account
}

variable "sentinel_external_id" {
  type        = string
  description = "External ID (your Sentinel workspace ID) used to scope the AssumeRole trust."
  sensitive   = true
  default     = "00000000-0000-0000-0000-000000000000"
}

data "aws_caller_identity" "current" {}

# Customer-managed KMS key for CloudTrail + S3 at-rest encryption (with rotation).
resource "aws_kms_key" "cloudtrail" {
  description             = "CMK for Sentinel CloudTrail log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/sentinel-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "AllowRootAccountAdmin"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
  statement {
    sid       = "AllowCloudTrailEncrypt"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

# CloudTrail log bucket.
resource "aws_s3_bucket" "sentinel_cloudtrail" {
  bucket = "sentinel-multi-cloud-trail-logs-${data.aws_caller_identity.current.account_id}"
  #tfsec:ignore:aws-s3-enable-bucket-logging - object-level access is captured by the CloudTrail data events on this trail; a self-referential S3 server-access-log bucket is out of scope for this demo module.
}

resource "aws_s3_bucket_public_access_block" "sentinel_cloudtrail" {
  bucket                  = aws_s3_bucket.sentinel_cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id

  versioning_configuration {
    status = "Enabled"
  }
}

# CloudTrail requires write access to the bucket via a bucket policy.
data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.sentinel_cloudtrail.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.sentinel_cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

# CloudTrail configuration (multi-region, KMS-encrypted, log-file validation on).
resource "aws_cloudtrail" "sentinel_trail" {
  name                          = "sentinel-security-trail"
  s3_bucket_name                = aws_s3_bucket.sentinel_cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn

  depends_on = [aws_s3_bucket_policy.sentinel_cloudtrail]
}

# OIDC IAM role for Azure Sentinel cross-cloud trust (scoped via external ID).
resource "aws_iam_role" "sentinel_aws_connector" {
  name = "AzureSentinelAWSIntegrationRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.sentinel_aws_account_id}:root"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.sentinel_external_id
          }
        }
      }
    ]
  })
}

# Attach least-privilege read access for Sentinel to pull CloudTrail logs from S3.
resource "aws_iam_role_policy_attachment" "sentinel_s3_read" {
  role       = aws_iam_role.sentinel_aws_connector.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# This module deploys a lab SOAR playbook shell via Azure Logic Apps.
# Containment permissions are opt-in and should be scoped to an approved lab target.
terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "location" {
  type        = string
  description = "Azure region for the SOAR resource group."
  default     = "eastus"
}

variable "enable_network_containment_role" {
  type        = bool
  description = "Opt-in switch for granting Network Contributor to the playbook identity in a lab containment scope."
  default     = false
}

variable "containment_scope_resource_group_id" {
  type        = string
  description = "Optional resource group ID containing lab NSGs that the playbook is allowed to modify."
  default     = ""
}

resource "azurerm_resource_group" "soar" {
  name     = "rg-sentinel-soar-lab"
  location = var.location
}

# The Logic App Workflow (the SOAR playbook).
resource "azurerm_logic_app_workflow" "isolate_host" {
  name                = "playbook-isolate-compromised-host"
  location            = azurerm_resource_group.soar.location
  resource_group_name = azurerm_resource_group.soar.name

  identity {
    type = "SystemAssigned"
  }
}

# Least privilege: Network Contributor is disabled by default and must be explicitly
# enabled for a lab resource group. Do not scope this to the whole subscription.
resource "azurerm_role_assignment" "soar_network_contributor" {
  count                = var.enable_network_containment_role ? 1 : 0
  scope                = var.containment_scope_resource_group_id != "" ? var.containment_scope_resource_group_id : azurerm_resource_group.soar.id
  role_definition_name = "Network Contributor"
  principal_id         = azurerm_logic_app_workflow.isolate_host.identity[0].principal_id
}

# NOTE: Revoking Entra ID sessions is a Microsoft Graph (directory) permission, not an
# Azure RBAC role. In production, grant this managed identity the Graph app role
# (e.g. User.RevokeSessions.All) via the azuread provider. It is intentionally NOT a
# subscription-scoped "User Administrator" assignment, which would be wildly over-privileged.

# This Terraform module provisions a temporary Windows honeypot for attack simulation.
# SECURITY: the admin credential is generated at apply time with random_password and is
# never committed to source control. For a production deployment, persist it to Azure
# Key Vault and reference it through a data source rather than emitting it as an output.
terraform {
  required_providers {
    azurerm = { source = "hashicorp/azurerm", version = "~> 3.0" }
    random  = { source = "hashicorp/random", version = "~> 3.6" }
  }
}

provider "azurerm" {
  features {}
}

# Generated at apply time - replaces the previously hard-coded plaintext password.
resource "random_password" "honeypot_admin" {
  length           = 24
  special          = true
  override_special = "!@#%*()-_=+"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "azurerm_resource_group" "honeypot" {
  name     = "rg-sentinel-honeypot-temp"
  location = "eastus"
}

resource "azurerm_virtual_network" "vnet" {
  name                = "vnet-honeypot"
  address_space       = ["10.0.0.0/16"]
  location            = azurerm_resource_group.honeypot.location
  resource_group_name = azurerm_resource_group.honeypot.name
}

resource "azurerm_subnet" "subnet" {
  name                 = "internal"
  resource_group_name  = azurerm_resource_group.honeypot.name
  virtual_network_name = azurerm_virtual_network.vnet.name
  address_prefixes     = ["10.0.2.0/24"]
}

resource "azurerm_network_interface" "nic" {
  name                = "nic-honeypot"
  location            = azurerm_resource_group.honeypot.location
  resource_group_name = azurerm_resource_group.honeypot.name

  ip_configuration {
    name                          = "internal"
    subnet_id                     = azurerm_subnet.subnet.id
    private_ip_address_allocation = "Dynamic"
  }
}

resource "azurerm_windows_virtual_machine" "honeypot_vm" {
  name                  = "vm-honeypot-01"
  resource_group_name   = azurerm_resource_group.honeypot.name
  location              = azurerm_resource_group.honeypot.location
  size                  = "Standard_B2s"
  admin_username        = "socadmin"
  admin_password        = random_password.honeypot_admin.result # generated, never committed
  network_interface_ids = [azurerm_network_interface.nic.id]

  os_disk {
    caching              = "ReadWrite"
    storage_account_type = "Standard_LRS"
  }

  source_image_reference {
    publisher = "MicrosoftWindowsServer"
    offer     = "WindowsServer"
    sku       = "2022-Datacenter"
    version   = "latest"
  }
}

output "honeypot_admin_password" {
  description = "Generated honeypot admin password. Retrieve with: terraform output -raw honeypot_admin_password"
  value       = random_password.honeypot_admin.result
  sensitive   = true
}

# Azure Policy enforcement layer — turns "detect" controls into "prevent".
# Deploys custom deny/audit policy definitions plus the built-in Microsoft Cloud
# Security Benchmark initiative, assigned at subscription scope. This is the
# preventative complement to the Sentinel detections: misconfigurations are
# blocked at deployment time, not just alerted on after the fact.
terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "subscription_id" {
  type        = string
  description = "Target subscription ID (GUID) for policy assignment."
  default     = "00000000-0000-0000-0000-000000000000"
}

variable "location" {
  type        = string
  description = "Region for policy assignment managed identities."
  default     = "eastus"
}

locals {
  subscription_scope = "/subscriptions/${var.subscription_id}"
}

# 1. Deny storage accounts that do not enforce HTTPS-only (secure transfer).
resource "azurerm_policy_definition" "require_https_storage" {
  name         = "deny-storage-without-secure-transfer"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Deny storage accounts without secure transfer (HTTPS)"
  description  = "Blocks creation of storage accounts that allow unencrypted HTTP traffic."

  policy_rule = jsonencode({
    if = {
      allOf = [
        { field = "type", equals = "Microsoft.Storage/storageAccounts" },
        { field = "Microsoft.Storage/storageAccounts/supportsHttpsTrafficOnly", notEquals = "true" }
      ]
    }
    then = { effect = "deny" }
  })
}

# 2. Deny public network access on storage accounts.
resource "azurerm_policy_definition" "deny_public_storage" {
  name         = "deny-storage-public-network-access"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Deny storage accounts with public network access enabled"
  description  = "Blocks storage accounts that are reachable from the public internet."

  policy_rule = jsonencode({
    if = {
      allOf = [
        { field = "type", equals = "Microsoft.Storage/storageAccounts" },
        { field = "Microsoft.Storage/storageAccounts/publicNetworkAccess", notEquals = "Disabled" }
      ]
    }
    then = { effect = "deny" }
  })
}

# 3. Audit virtual machines that are missing managed-disk encryption settings.
resource "azurerm_policy_definition" "audit_unencrypted_vm" {
  name         = "audit-vm-without-encryption-at-host"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Audit VMs without encryption at host"
  description  = "Flags virtual machines that do not have encryption at host enabled."

  policy_rule = jsonencode({
    if = {
      allOf = [
        { field = "type", equals = "Microsoft.Compute/virtualMachines" },
        { field = "Microsoft.Compute/virtualMachines/securityProfile.encryptionAtHost", notEquals = "true" }
      ]
    }
    then = { effect = "audit" }
  })
}

# 4. Deny anonymous public access on blob containers.
resource "azurerm_policy_definition" "deny_public_blob_access" {
  name         = "deny-public-blob-container-access"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Deny public blob container access"
  description  = "Blocks blob containers that allow anonymous public access."

  policy_rule = jsonencode({
    if = {
      allOf = [
        { field = "type", equals = "Microsoft.Storage/storageAccounts/blobServices/containers" },
        { field = "Microsoft.Storage/storageAccounts/blobServices/containers/publicAccess", notEquals = "None" }
      ]
    }
    then = { effect = "deny" }
  })
}

# 5. Audit public IP resources so internet exposure is visible.
resource "azurerm_policy_definition" "audit_public_ip" {
  name         = "audit-public-ip-resources"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Audit public IP resources"
  description  = "Flags public IP resources for review and exposure tracking."

  policy_rule = jsonencode({
    if = {
      field  = "type"
      equals = "Microsoft.Network/publicIPAddresses"
    }
    then = { effect = "audit" }
  })
}

# 6. Require core ownership tags for cost and accountability.
resource "azurerm_policy_definition" "require_owner_environment_tags" {
  name         = "audit-missing-owner-environment-tags"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Audit resources missing owner/environment tags"
  description  = "Flags resources that are missing owner or environment tags."

  policy_rule = jsonencode({
    if = {
      anyOf = [
        { field = "tags['owner']", exists = "false" },
        { field = "tags['environment']", exists = "false" }
      ]
    }
    then = { effect = "audit" }
  })
}

# 7. Audit storage accounts that allow TLS versions below 1.2.
resource "azurerm_policy_definition" "audit_weak_storage_tls" {
  name         = "audit-storage-weak-tls"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Audit storage accounts with weak TLS"
  description  = "Flags storage accounts that do not require TLS 1.2 or newer."

  policy_rule = jsonencode({
    if = {
      allOf = [
        { field = "type", equals = "Microsoft.Storage/storageAccounts" },
        { field = "Microsoft.Storage/storageAccounts/minimumTlsVersion", notEquals = "TLS1_2" }
      ]
    }
    then = { effect = "audit" }
  })
}

# 8. Audit Key Vault diagnostic settings. A deployIfNotExists version would need
# workspace-specific parameters and managed identity permissions.
resource "azurerm_policy_definition" "audit_keyvault_diagnostics" {
  name         = "audit-keyvault-diagnostics"
  policy_type  = "Custom"
  mode         = "Indexed"
  display_name = "Audit Key Vault diagnostic settings"
  description  = "Flags Key Vault resources so diagnostic settings can be routed to Log Analytics/Sentinel."

  policy_rule = jsonencode({
    if = {
      field  = "type"
      equals = "Microsoft.KeyVault/vaults"
    }
    then = { effect = "audit" }
  })
}

# Assign the custom deny policies at subscription scope.
resource "azurerm_subscription_policy_assignment" "require_https_storage" {
  name                 = "require-https-storage"
  display_name         = "Deny storage without HTTPS"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.require_https_storage.id
}

resource "azurerm_subscription_policy_assignment" "deny_public_storage" {
  name                 = "deny-public-storage"
  display_name         = "Deny public storage network access"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.deny_public_storage.id
}

resource "azurerm_subscription_policy_assignment" "audit_unencrypted_vm" {
  name                 = "audit-vm-encryption"
  display_name         = "Audit VMs without encryption at host"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.audit_unencrypted_vm.id
}

resource "azurerm_subscription_policy_assignment" "deny_public_blob_access" {
  name                 = "deny-public-blob-access"
  display_name         = "Deny public blob container access"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.deny_public_blob_access.id
}

resource "azurerm_subscription_policy_assignment" "audit_public_ip" {
  name                 = "audit-public-ip"
  display_name         = "Audit public IP resources"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.audit_public_ip.id
}

resource "azurerm_subscription_policy_assignment" "require_owner_environment_tags" {
  name                 = "audit-owner-env-tags"
  display_name         = "Audit owner/environment tags"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.require_owner_environment_tags.id
}

resource "azurerm_subscription_policy_assignment" "audit_weak_storage_tls" {
  name                 = "audit-storage-weak-tls"
  display_name         = "Audit storage weak TLS"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.audit_weak_storage_tls.id
}

resource "azurerm_subscription_policy_assignment" "audit_keyvault_diagnostics" {
  name                 = "audit-keyvault-diagnostics"
  display_name         = "Audit Key Vault diagnostic settings"
  subscription_id      = local.subscription_scope
  policy_definition_id = azurerm_policy_definition.audit_keyvault_diagnostics.id
}

# 9. Assign the built-in Microsoft Cloud Security Benchmark initiative for
#    continuous, audit-wide compliance baselining.
data "azurerm_policy_set_definition" "mcsb" {
  display_name = "Microsoft cloud security benchmark"
}

resource "azurerm_subscription_policy_assignment" "mcsb" {
  name                 = "mcsb-baseline"
  display_name         = "Microsoft Cloud Security Benchmark"
  subscription_id      = local.subscription_scope
  policy_definition_id = data.azurerm_policy_set_definition.mcsb.id
  location             = var.location

  identity {
    type = "SystemAssigned"
  }
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	subscriptionID := flag.String("sub", "", "Azure Subscription ID")
	resourceGroup := flag.String("rg", "", "Azure Resource Group")
	workspaceName := flag.String("workspace", "", "Sentinel workspace name")
	rulesDir := flag.String("dir", "../sentinel-detection-pack/rules-yaml", "Directory containing YAML rules")
	apply := flag.Bool("apply", false, "Apply changes to Sentinel. Default is dry-run validation and mapping only.")
	dryRun := flag.Bool("dry-run", false, "Force dry-run mode even when other flags are present.")
	explain := flag.Bool("explain", false, "Print a reviewer-friendly explanation of each mapped rule during dry-run.")
	validateJSON := flag.Bool("validate-json", false, "Write validation report JSON to stdout unless -output is set.")
	output := flag.String("output", "", "Optional path for validation report JSON.")
	flag.Parse()

	effectiveApply := *apply && !*dryRun
	if effectiveApply && (*subscriptionID == "" || *resourceGroup == "" || *workspaceName == "") {
		log.Fatal("Error: -sub, -rg, and -workspace are required when -apply is used.")
	}

	mode := "DRY-RUN"
	if effectiveApply {
		mode = "APPLY"
	}
	fmt.Printf("Initializing Sentinel Detection-as-Code deployer [mode=%s]\n", mode)

	deployer, err := NewDeployer(*subscriptionID, *resourceGroup, *workspaceName, effectiveApply, *explain)
	if err != nil {
		log.Fatalf("Failed to initialize deployer: %v", err)
	}

	var validations []RuleValidation
	var processed, failed int
	err = filepath.Walk(*rulesDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info == nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(info.Name(), ".yaml") && !strings.HasSuffix(info.Name(), ".yml") {
			return nil
		}

		fmt.Printf("Processing rule: %s\n", info.Name())
		validation, deployErr := deployer.DeployRule(path)
		validations = append(validations, validation)
		if deployErr != nil {
			log.Printf("Failed to process %s: %v", info.Name(), deployErr)
			failed++
			return nil
		}
		processed++
		return nil
	})
	if err != nil {
		log.Fatalf("Error walking rules directory: %v", err)
	}

	report := BuildValidationReport(validations)
	if *validateJSON || strings.TrimSpace(*output) != "" {
		if err := writeValidationReport(report, *output); err != nil {
			log.Fatalf("Failed to write validation report: %v", err)
		}
	}

	fmt.Printf("Detection-as-Code run completed. (%d processed, %d failed, %d warnings)\n", processed, failed, report.Summary.Warnings)
	if failed > 0 || report.Summary.Failed > 0 {
		os.Exit(1)
	}
}

func writeValidationReport(report ValidationReport, outputPath string) error {
	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		return err
	}
	if strings.TrimSpace(outputPath) == "" {
		fmt.Println(string(data))
		return nil
	}
	return os.WriteFile(outputPath, append(data, '\n'), 0o644)
}

